+{
+  config,
+  options,
+  lib,
+  ...
+}:
+
+let
+  inherit (lib)
+    concatStringsSep
+    isBool
+    mapAttrs
+    mkEnableOption
+    mkOption
+    mkPackageOption
+    mkRenamedOptionModule
+    types
+    ;
+
+  cfg = config.redlib;
+
+  args = concatStringsSep " " [
+    "--port ${toString cfg.port}"
+    "--address ${cfg.address}"
+  ];
+
+  boolToString' = b: if b then "on" else "off";
+in
+{
+  _class = "service";
+
+  options = {
+    redlib = {
+      package = lib.options.mkModularPackageOption "redlib" { };
+
